   771|  const probe = await checkDatabaseHealth();
   772|  if (probe.ok) {
   773|    tableEnsured = true;
   774|    return true;
   775|  }
   776|  const token = (process.env.SUPABASE_ACCESS_TOKEN ?? '').trim();
   777|  if (!token) {
   778|    console.log('[IVXOwnerAITaskQueue] table missing and SUPABASE_ACCESS_TOKEN absent — cannot self-bootstrap DDL');
   779|    return false;
