   781|  for (let attempt = 1; attempt <= DDL_RETRY_ATTEMPTS; attempt++) {
   782|    try {
   783|      const res = await fetch(`${MANAGEMENT_API_BASE}/projects/${managementProjectRef()}/database/query`, {
   784|        method: 'POST',
   785|        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
   786|        body: JSON.stringify({ query: TASK_TABLE_DDL }),
   787|        signal: AbortSignal.timeout(30_000),
   788|      });
   789|      console.log('[IVXOwnerAITaskQueue] self-bootstrap DDL result', { attempt, httpStatus: res.status });
   790|      if (res.ok || res.status === 201) {
   791|        tableEnsured = true;
   792|        return true;
   793|      }
   794|      if (!isTransientBootstrapStatus(res.status) || attempt === DDL_RETRY_ATTEMPTS) {
   795|        return false;
   796|      }
   797|      await sleep(DDL_RETRY_BASE_MS * attempt);
